#[no_mangle]
pub unsafe extern "C" fn iso10126_d2_padding(v:*const i64,n:usize,out:*mut u8,cap:usize)->i64{if v.is_null()||n<2||n>66{return -1}let a=std::slice::from_raw_parts(v,n);let mode=a[0];if mode==0{if n<3{return -1}let(off,len)=(a[1],a[2]);if !(1..=64).contains(&len)||off<0||off>=len||n!=3+off as usize+(len-off-1)as usize{return -1}if a[3..].iter().any(|x|!(0..=255).contains(x)){return -1}if a[3+off as usize..].iter().any(|x|*x>=255){return -1}let bytes=len as usize+1;if out.is_null()||cap<bytes{return -2}let dst=std::slice::from_raw_parts_mut(out,bytes);let count=(len-off)as u8;dst[0]=count;for i in 0..off as usize{dst[1+i]=a[3+i]as u8}let mut at=1+off as usize;for x in &a[3+off as usize..]{dst[at]=*x as u8;at+=1}dst[at]=count;return bytes as i64}if !(mode==1||mode==2)||n<3{return -1}let len=a[1];if !(1..=64).contains(&len)||n!=2+len as usize||a[2..].iter().any(|x|!(0..=255).contains(x)){return -1}let count=a[n-1];if count<1||count>len{return -1}let bytes=if mode==1{(len-count)as usize}else{1};if out.is_null()||cap<bytes{return -2}let dst=std::slice::from_raw_parts_mut(out,bytes);if mode==1{for i in 0..bytes{dst[i]=a[2+i]as u8}}else{dst[0]=count as u8}bytes as i64}
